body.content:
.home-conversion-hero {
  position: relative;
  overflow: hidden;
  color: var(--home-hero-text, #201613);
  background:
    radial-gradient(circle at top right, rgba(244, 170, 93, 0.22), transparent 32rem),
    linear-gradient(135deg, var(--home-hero-bg-start, #f6efe7) 0%, var(--home-hero-bg-end, #fdf9f4) 100%);
}

.home-conversion-hero::before {
  content: '';
  position: absolute;
  inset: auto auto -7rem -5rem;
  width: 16rem;
  height: 16rem;
  border-radius: 999px;
  background: rgba(200, 121, 50, 0.14);
  filter: blur(6px);
}

.home-conversion-hero__media {
  position: absolute;
  inset: 0;
  pointer-events: none;
  opacity: 0.18;
}

.home-conversion-hero__media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
}

.home-conversion-hero__shell {
  position: relative;
  z-index: 1;
}

.home-conversion-hero__inner {
  display: grid;
  gap: 2rem;
  align-items: start;
}

.home-conversion-hero__content {
  display: flex;
  flex-direction: column;
  gap: 1rem;
}

.home-conversion-hero__trust {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.home-conversion-hero__trust-item,
.home-conversion-hero__trust-link {
  display: inline-flex;
  align-items: center;
  gap: 0.55rem;
  padding: 0.7rem 0.95rem;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.84);
  border: 1px solid rgba(32, 22, 19, 0.1);
  color: inherit;
  text-decoration: none;
  font-size: 0.92rem;
  line-height: 1.2;
  box-shadow: 0 10px 30px rgba(32, 22, 19, 0.06);
  backdrop-filter: blur(10px);
}

.home-conversion-hero__trust-icon {
  color: var(--home-hero-accent, #c87932);
  flex-shrink: 0;
}

.home-conversion-hero__eyebrow {
  display: inline-flex;
  align-self: flex-start;
  align-items: center;
  gap: 0.5rem;
  margin: 0;
  padding: 0.45rem 0.8rem;
  border-radius: 999px;
  background: rgba(200, 121, 50, 0.12);
  color: var(--home-hero-accent, #c87932);
  font-size: 0.82rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.home-conversion-hero__title {
  margin: 0;
  max-width: 14ch;
  color: inherit;
  font-size: clamp(2.15rem, 5vw, 4.5rem);
  line-height: 0.95;
  letter-spacing: -0.04em;
}

.home-conversion-hero__body {
  margin: 0;
  max-width: 36rem;
  font-size: 1.02rem;
  line-height: 1.65;
  color: rgba(32, 22, 19, 0.8);
}

.home-conversion-hero__cta-group {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.home-conversion-hero__cta-group .button {
  min-width: 12rem;
}

.home-conversion-hero__supporting-links {
  display: flex;
  flex-wrap: wrap;
  gap: 0.75rem;
}

.home-conversion-hero__supporting-link {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  color: inherit;
  font-size: 0.95rem;
  font-weight: 600;
  text-decoration: none;
}

.home-conversion-hero__supporting-link .icon-wrap {
  display: inline-flex;
  transition: transform 0.2s ease;
}

.home-conversion-hero__supporting-link:hover .icon-wrap {
  transform: translateX(2px);
}

.home-conversion-hero__products {
  display: flex;
  gap: 1rem;
  overflow-x: auto;
  scroll-snap-type: x proximity;
  padding-bottom: 0.4rem;
  margin-inline: -1.5rem;
  padding-inline: 1.5rem;
}

.home-conversion-hero__product-item {
  flex: 0 0 min(82vw, 18rem);
  scroll-snap-align: start;
}

.home-spotlight-card {
  display: flex;
  flex-direction: column;
  height: 100%;
  border-radius: 1.45rem;
  overflow: hidden;
  border: 1px solid rgba(32, 22, 19, 0.08);
  background: var(--home-spotlight-card-bg, #fffdf9);
  box-shadow: 0 22px 50px rgba(32, 22, 19, 0.08);
}

.home-spotlight-card__media {
  display: block;
  aspect-ratio: 4 / 5;
  background: rgba(232, 214, 193, 0.4);
}

.home-spotlight-card__media img {
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.home-spotlight-card__content {
  display: flex;
  flex: 1;
  flex-direction: column;
  gap: 0.8rem;
  padding: 0.95rem 0.95rem 1rem;
}

.home-spotlight-card__badge {
  margin: 0;
  color: var(--home-hero-accent, #c87932);
  font-size: 0.75rem;
  font-weight: 700;
  letter-spacing: 0.08em;
  text-transform: uppercase;
}

.home-spotlight-card__title {
  margin: 0;
  font-size: 1.05rem;
  line-height: 1.25;
}

.home-spotlight-card__title a {
  color: inherit;
  text-decoration: none;
}

.home-spotlight-card__caption {
  margin: 0;
  color: rgba(32, 22, 19, 0.7);
  font-size: 0.95rem;
  line-height: 1.5;
}

.home-spotlight-card__price .price__container {
  display: flex;
  flex-wrap: wrap;
  gap: 0.35rem;
  align-items: baseline;
}

.home-spotlight-card__price .price-item {
  font-size: 1rem;
}

.home-spotlight-card__price .price-item--sale,
.home-spotlight-card__price .price-item--regular {
  color: inherit;
}

.home-spotlight-card__cta {
  width: 100%;
  justify-content: center;
}

.home-spotlight-card__actions {
  display: flex;
  flex-direction: column;
  gap: 0.45rem;
  margin-top: auto;
}

.home-spotlight-card__trust {
  margin: 0;
  color: rgba(32, 22, 19, 0.68);
  font-size: 0.82rem;
  line-height: 1.45;
}

.home-spotlight-card__collection-link {
  display: inline-flex;
  align-items: center;
  gap: 0.35rem;
  align-self: flex-start;
  color: inherit;
  font-size: 0.9rem;
  font-weight: 600;
  text-decoration: none;
}

.home-spotlight-card__collection-link .icon-wrap {
  display: inline-flex;
  transition: transform 0.2s ease;
}

.home-spotlight-card__collection-link:hover .icon-wrap {
  transform: translateX(2px);
}

.curated-product-grid__header {
  display: flex;
  flex-direction: column;
  gap: 1.4rem;
  margin-bottom: 1.6rem;
}

.curated-product-grid__title {
  margin: 0;
  font-size: 2.8rem;
  line-height: 1.05;
  letter-spacing: 0;
}

.curated-product-grid__intro {
  margin: 0;
  max-width: 58rem;
  color: rgba(32, 22, 19, 0.72);
  font-size: 1.45rem;
  line-height: 1.55;
}

.curated-product-grid__intro p {
  margin: 0;
}

.curated-product-grid__grid {
  display: grid;
  gap: 1.4rem;
  grid-template-columns: repeat(1, minmax(0, 1fr));
}

.curated-product-grid__empty {
  margin: 0;
}

.curated-product-grid .home-spotlight-card {
  border-color: rgba(32, 22, 19, 0.1);
  box-shadow: 0 24px 58px rgba(32, 22, 19, 0.1);
}

.curated-product-grid .home-spotlight-card__media {
  position: relative;
  aspect-ratio: auto;
  overflow: hidden;
}

.curated-product-grid .home-spotlight-card__media::before {
  content: '';
  display: block;
  padding-bottom: 125%;
}

.curated-product-grid .home-spotlight-card__media img,
.curated-product-grid .home-spotlight-card__media .placeholder-svg {
  position: absolute;
  inset: 0;
  width: 100%;
  height: 100%;
  object-fit: cover;
}

.curated-product-grid .home-spotlight-card__media img {
  transition: transform 0.28s ease;
}

.curated-product-grid .home-spotlight-card__content {
  gap: 1rem;
  padding: 1.25rem 1.25rem 1.35rem;
}

.curated-product-grid .home-spotlight-card__badge {
  font-size: 0.95rem;
  letter-spacing: 0.06em;
}

.curated-product-grid .home-spotlight-card__title {
  font-size: 1.7rem;
  line-height: 1.18;
  letter-spacing: 0;
}

.curated-product-grid .home-spotlight-card__caption {
  font-size: 1.25rem;
  line-height: 1.55;
}

.curated-product-grid .home-spotlight-card__price .price-item {
  font-size: 1.35rem;
}

.curated-product-grid .home-spotlight-card__collection-link {
  font-size: 1.2rem;
  line-height: 1.3;
}

@media screen and (min-width: 750px) {
  .home-conversion-hero__inner {
    gap: 2.5rem;
  }

  .home-conversion-hero__products {
    margin-inline: 0;
    padding-inline: 0;
  }

  .curated-product-grid__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 1.8rem;
  }

  .curated-product-grid__title {
    font-size: 3.4rem;
  }

  .curated-product-grid__intro {
    font-size: 1.55rem;
  }

  .curated-product-grid .home-spotlight-card__content {
    padding: 1.45rem 1.45rem 1.55rem;
  }

  .curated-product-grid .home-spotlight-card__title {
    font-size: 1.9rem;
  }

  .curated-product-grid .home-spotlight-card__caption {
    font-size: 1.32rem;
  }
}

@media screen and (min-width: 990px) {
  .home-conversion-hero__inner {
    grid-template-columns: minmax(0, 1.08fr) minmax(0, 0.92fr);
  }

  .home-conversion-hero__content {
    padding-top: 0.75rem;
  }

  .home-conversion-hero__products {
    display: grid;
    grid-template-columns: repeat(2, minmax(0, 1fr));
    align-self: stretch;
    overflow: visible;
  }

  .home-conversion-hero__product-item {
    min-width: 0;
  }

  .curated-product-grid__header {
    flex-direction: row;
    align-items: center;
    justify-content: space-between;
    margin-bottom: 2.4rem;
  }

  .curated-product-grid__grid {
    grid-template-columns: repeat(2, minmax(0, 1fr));
    gap: 2.4rem;
  }

  .curated-product-grid__header .button {
    min-width: 20rem;
  }

  .curated-product-grid .home-spotlight-card:hover .home-spotlight-card__media img {
    transform: scale(1.035);
  }

  .curated-product-grid .home-spotlight-card__content {
    padding: 1.65rem 1.65rem 1.75rem;
  }

  .curated-product-grid .home-spotlight-card__title {
    font-size: 2.05rem;
  }

  .curated-product-grid .home-spotlight-card__caption {
    font-size: 1.38rem;
  }
}

@media screen and (max-width: 749px) {
  .home-conversion-hero__trust-item,
  .home-conversion-hero__trust-link {
    width: 100%;
    justify-content: center;
  }

  .home-conversion-hero__title {
    max-width: none;
  }

  .home-conversion-hero__cta-group .button {
    width: 100%;
  }

  .curated-product-grid__header .button {
    width: 100%;
  }
}

